{
  "narratives": [
    {
      "item_code": "S7_HANDLING",
      "title_raw": "가. 안전취급요령",
      "start": "p6:L1",
      "end": "p6:L13"
    },
    {
      "item_code": "S7_STORAGE",
      "title_raw": "나. 안전한 저장방법",
      "start": "p6:L14",
      "end": "p6:L17"
    }
  ],
  "extras": [
    {
      "after_item": "S7_END",
      "title_raw": "가. 안전취급요령",
      "reason": "코드없음",
      "statements": [
        {
          "value": "압력을 가하거나, 자르거나, 용접, 납땜, 접합, 뚫기, 연마 또는 열에 폭로, 화염, 불꽃, 정전기 또는 다른 점화원에 폭로하지 마시오.",
          "line": "p6:L2"
        },
        {
          "value": "환기가 잘 되는 지역에서만 사용하시오.",
          "line": "p6:L4"
        },
        {
          "value": "용기가 비워진 후에도 제품 찌꺼기가 남아 있을 수 있으므로 모든 MSDS/라벨 예방조치를 따르시오.",
          "line": "p6:L5"
        },
        {
          "value": "취급/저장에 주의하여 사용하시오.",
          "line": "p6:L6"
        },
        {
          "value": "개봉 전에 조심스럽게 마개를 여시오.",
          "line": "p6:L7"
        },
        {
          "value": "가열된 물질에서 발생하는 증기를 호흡하지 마시오.",
          "line": "p6:L8"
        },
        {
          "value": "적절한 환기가 없으면 저장지역에 출입하지 마시오.",
          "line": "p6:L9"
        },
        {
          "value": "물질 취급시 모든 장비를 반드시 접지하시오.",
          "line": "p6:L10"
        },
        {
          "value": "피해야할 물질 및 조건에 유의하시오.",
          "line": "p6:L11"
        },
        {
          "value": "공학적 관리 및 개인보호구를 참조하여 작업하시오.",
          "line": "p6:L12"
        },
        {
          "value": "장기간 또는 지속적인 피부접촉을 막으시오.",
          "line": "p6:L13"
        }
      ],
      "line": "p6:L1"
    },
    {
      "after_item": "S7_HANDLING",
      "title_raw": "나. 안전한 저장방법",
      "reason": "코드없음",
      "statements": [
        {
          "value": "빈 드럼통은 완전히 배수하고 적절히 막아 즉시 드럼 조절기에 되돌려 놓거나 적절히 배치하시오.",
          "line": "p6:L15"
        },
        {
          "value": "용기는 열에 노출되었을 경우 압력이 올라갈 수 있으므로 열에 폭로되지 않도록 하시오.",
          "line": "p6:L16"
        },
        {
          "value": "밀폐하여 보관하시오.",
          "line": "p6:L17"
        }
      ],
      "line": "p6:L14"
    }
  ]
}

